#!/usr/bin/env bash
# volume.sh smoke: a stub wpctl (VOLUME_WPCTL) answers get/set; the real wpctl is never run.
for _a in "$@"; do case "$_a" in --help|-h)
	printf 'usage: %s %s\n' "${0##*/}" ''
	printf '%s\n' 'Hermetic smoke for util/volume.sh against a stub wpctl; takes no arguments.'
	exit 0;; esac; done
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/tests/volume.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'volume.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
_bid="$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../lib/build-id.sh"
# shellcheck source=util/lib/build-id.sh
[ -r "$_bid" ] && { . "$_bid"; build_flags "${BASH_SOURCE[0]}" "$@"; }
set -eu

test_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
root=$(mktemp -d)
trap 'rm -rf "$root"' EXIT
# a copy in a fixture repo, so a live repo-root config.sh cannot leak in
mkdir -p "$root/repo/util"
cp -R "$test_dir/../volume.sh" "$test_dir/../lib" "$root/repo/util/"
script="$root/repo/util/volume.sh"

pass_count=0
fail_count=0

check() {
	local description=$1 expected=$2 actual=$3
	if [[ "$actual" == *"$expected"* ]]; then
		printf 'ok %d - %s\n' "$((pass_count + fail_count + 1))" "$description"
		pass_count=$((pass_count + 1))
	else
		printf 'not ok %d - %s\n  expected substring: %q\n  actual: %q\n' \
			"$((pass_count + fail_count + 1))" "$description" "$expected" "$actual" >&2
		fail_count=$((fail_count + 1))
	fi
}

absent() {
	local description=$1 unexpected=$2 actual=$3
	if [[ "$actual" != *"$unexpected"* ]]; then
		check "$description" "" ""
	else
		check "$description" "(no $unexpected)" "$actual"
	fi
}

# stub wpctl: get-volume prints a fixed reading (MUTED when STUB_MUTED=1),
# set-volume appends its argv to the log; the real wpctl is never run
log="$root/wpctl.log"
cat > "$root/wpctl" <<'STUB'
#!/bin/sh
case "$1" in
	get-volume) if [ "${STUB_MUTED:-0}" = 1 ]; then echo 'Volume: 0.42 [MUTED]'; else echo 'Volume: 0.42'; fi ;;
	set-volume) printf '%s\n' "$*" >> "$STUB_LOG" ;;
	*) exit 9 ;;
esac
STUB
chmod +x "$root/wpctl"
export VOLUME_WPCTL="$root/wpctl" STUB_LOG="$log" AUDIO_SINK=
log_state() { if [ -s "$log" ]; then echo dirty; else echo clean; fi; }
: > "$log"

rc=0; out=$(bash "$script") || rc=$?
check "bare exit 0" "0" "$rc"
check "bare prints percent" "42%" "$out"
absent "bare unmuted has no muted" "muted" "$out"
out=$(STUB_MUTED=1 bash "$script")
check "muted reading" "42% muted" "$out"
check "bare log empty" "clean" "$(log_state)"

for v in 0 100 007; do
	: > "$log"
	rc=0; bash "$script" "$v" || rc=$?
	check "set $v exit 0" "0" "$rc"
	check "set $v argv" "set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ $((10#$v))%" "$(cat "$log")"
done

: > "$log"
AUDIO_SINK=57 bash "$script" 30
check "env AUDIO_SINK wins" "set-volume -l 1.0 57 30%" "$(cat "$log")"

: > "$log"
printf "%s\n" "AUDIO_SINK=cfg-sink" > "$root/repo/config.sh"
bash "$script" 30
check "repo config.sh sink is used" "set-volume -l 1.0 cfg-sink 30%" "$(cat "$log")"
: > "$log"
AUDIO_SINK=57 bash "$script" 30
check "env AUDIO_SINK beats config.sh" "set-volume -l 1.0 57 30%" "$(cat "$log")"
rm "$root/repo/config.sh"

for v in 101 -1 abc ''; do
	: > "$log"
	rc=0; err=$(bash "$script" "$v" 2>&1 >/dev/null) || rc=$?
	check "reject <$v> exit 2" "2" "$rc"
	check "reject <$v> usage" "usage: util volume [0-100]" "$err"
	check "reject <$v> calls no set" "clean" "$(log_state)"
done

rc=0; help=$(bash "$script" --help) || rc=$?
check "--help exit 0" "0" "$rc"
check "--help usage" "usage:" "$help"
check "--complete offers levels" "50" "$(bash "$script" --complete 1 "")"
check "--help/--complete call no set" "clean" "$(log_state)"

printf '%d passed, %d failed\n' "$pass_count" "$fail_count"
[ "$fail_count" -eq 0 ]
